lure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-032"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.185, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-009 (0.18)"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}], "n_results": 4}

